# mitm plugin template

yakit_output(MITM_PARAMS)




#--------------------------WORKSPACE-----------------------------
isBypass = cli.Bool("isBypass", cli.setVerboseName("Bypass WAF"),cli.setDefault(false),cli.setCliGroup("config"))
prefix = cli.Text("prefix", cli.setVerboseName("字典前缀"),cli.setCliGroup("config"))
domains = cli.Text("domains", cli.setVerboseName("扫描域名"),cli.setCliGroup("config"))

cli.check()

#白名单检测状态
status = false
if domains != ""{
    domains = str.ParseStringToLines(domains)
    status = true
}


#扫描过的路径
scanPath := make([]string)
#绕过waf的路径
bypassWafPath = ["/.;","/test/..;","/"]
#api-docs字典
apiDocsDict = `
/openapi.json
/api-docs
/swagger.json
/swagger-resources
/v1/openapi.json
/v2/openapi.json
/v3/openapi.json
/v1/api-docs
/v2/api-docs
/v3/api-docs
/v1/swagger.json
/v2/swagger.json
/v3/swagger.json
/v1/swagger-resources
/v2/swagger-resources
/v3/swagger-resources
/api/v1/openapi.json
/api/v2/openapi.json
/api/v3/openapi.json
/api/v1/api-docs
/api/v2/api-docs
/api/v3/api-docs
/api/v1/swagger.json
/api/v2/swagger.json
/api/v3/swagger.json
/api/v1/swagger-resources
/api/v2/swagger-resources
/api/v3/swagger-resources
`
apiDocsDict = str.ParseStringToLines(apiDocsDict)

#swagger UI 字典
swaggerUiDict = `
/swagger.html
/swagger-ui/
/swagger-ui.html
/swagger/
/swagger-ui/index.html
/swagger/index.html
`
swaggerUiDict = str.ParseStringToLines(swaggerUiDict)

#后续扫描的api字典
scanApiDocsDict = make([]string)
#后续扫描的UI字典
scanSwaggerUiDict = make([]string)


#给字典添加前缀
if prefix != ""{
    prefixList = str.ParseStringToLines(prefix)
    for _, i = range prefixList{
        if !str.StartsWith(i, "/"){
            i = "/"+i
        }
        apiDocsDict = append(apiDocsDict, apiDocsDict.Map(fn(tmp){return i+tmp})...)
        swaggerUiDict = append(swaggerUiDict, swaggerUiDict.Map(fn(tmp){return i+tmp})...)
    }
}

scanApiDocsDict = append(scanApiDocsDict, apiDocsDict...)
scanSwaggerUiDict = append(scanSwaggerUiDict, swaggerUiDict...)

if isBypass{
    for _,i = range bypassWafPath{
        for _, j = range apiDocsDict{
            scanApiDocsDict.Push(i+j)
        }
        for _,j = range swaggerUiDict{
            scanSwaggerUiDict.Push(i+j)
        }
    }
}

parseUrl = func(url){
    return str.ExtractHostPort(url)
}

fingerApiDocs = [`"swagger"`,`"openapi"`,"swaggerVersion"]
fingerUi = ["Swagger","Swagger UI"]

# mirrorNewWebsite 每新出现一个网站，这个网站的第一个请求，将会在这里被调用！
mirrorNewWebsite = func(isHttps /*bool*/, url /*string*/, req /*[]byte*/, rsp /*[]byte*/, body /*[]byte*/) {
    if status {
        if !str.StringContainsAnyOfSubString(parseUrl(url), domains){
            return
        }
    }
    p = parseUrl(url) + "/"
    if p in scanPath{
        return
    }else{
        scanPath.Push(p)
        fuzzReq, err = fuzz.UrlToHTTPRequest("GET",url)
        if err != nil{
            yakit_output("生成fuzz失败")
            return
        }
        apiResults = fuzzReq.FuzzPath(scanApiDocsDict...).Exec(fuzz.WithTimeOut(5),httpool.https(isHttps))~
        for result = range apiResults{
            yakit.SaveHTTPFlow(result.Url, result.Request,result.Response )
            if str.StringContainsAnyOfSubString(string(result.ResponseRaw), fingerApiDocs) && result.Response.StatusCode == 200 && len(result.Response.Header["Content-Type"])>0 && str.Contains(result.Response.Header["Content-Type"][0], "json"){
                risk.NewRisk(result.Url,
                    risk.description("swagger API 泄露"),
                    risk.solution("1、生产环境禁止访问swagger"),
                    risk.title("swagger API 泄露"),
                    risk.request(result.RequestRaw),
                    risk.response(result.ResponseRaw),
                    risk.typeVerbose("swagger 未授权"),
                    risk.level("low")
                )
            }
        }
        swaggerUIResults = fuzzReq.FuzzPath(scanSwaggerUiDict...).Exec(fuzz.WithTimeOut(5),httpool.https(isHttps))~
        for result = range swaggerUIResults{
            yakit.SaveHTTPFlow(result.Url, result.Request,result.Response )
            if str.StringContainsAnyOfSubString(string(result.ResponseRaw), fingerUi) && result.Response.StatusCode == 200 && len(result.Response.Header["Content-Type"])>0 && str.Contains(result.Response.Header["Content-Type"][0], "html") {
                risk.NewRisk(result.Url,
                    risk.description("swagger UI 泄露"),
                    risk.solution("1、生产环境禁止访问swagger"),
                    risk.title("swagger UI 泄露"),
                    risk.request(result.RequestRaw),
                    risk.response(result.ResponseRaw),
                    risk.typeVerbose("swagger UI 未授权"),
                    risk.level("low")
                )
            }
        }
    }
    
}

# mirrorNewWebsitePath 每新出现一个网站路径，关于这个网站路径的第一个请求，将会在这里被传入回调
mirrorNewWebsitePath = func(isHttps /*bool*/, url /*string*/, req /*[]byte*/, rsp /*[]byte*/, body /*[]byte*/) {
    if status {
        if !str.StringContainsAnyOfSubString(parseUrl(url), domains){
            return
        }
    }
    path = ""
    hostPath = str.Split(url, "//")[1]
    if "/" in hostPath && len(str.Split(hostPath, "/"))>2{
        path = "/"+str.Split(hostPath, "/")[1]
    }else{
        return
    }
    p = parseUrl(url) + path
    if p in scanPath{
        return
    }else{
        scanPath.Push(p)
        Dict1 = scanApiDocsDict.Map(fn(i){return path+i})
        Dict2 = scanSwaggerUiDict.Map(fn(i){return path+i})
        fuzzReq, err = fuzz.UrlToHTTPRequest("GET",url)
        if err != nil{
            yakit_output("生成fuzz失败")
            return
        }
        apiResults = fuzzReq.FuzzPath(Dict1...).Exec(fuzz.WithTimeOut(5),httpool.https(isHttps))~
        for result = range apiResults{
            yakit.SaveHTTPFlow(result.Url, result.Request,result.Response )
            
            if str.StringContainsAnyOfSubString(string(result.ResponseRaw), fingerApiDocs) && result.Response.StatusCode == 200 && len(result.Response.Header["Content-Type"])>0 && str.Contains(result.Response.Header["Content-Type"][0], "json") {
                risk.NewRisk(result.Url,
                    risk.description("swagger API 泄露"),
                    risk.solution("1、生产环境禁止访问swagger"),
                    risk.title("swagger API 泄露"),
                    risk.request(result.RequestRaw),
                    risk.response(result.ResponseRaw),
                    risk.typeVerbose("swagger 未授权"),
                    risk.level("low")
                )
            }
        }
        swaggerUIResults = fuzzReq.FuzzPath(Dict2...).Exec(fuzz.WithTimeOut(5),httpool.https(isHttps))~
        for result = range swaggerUIResults{
            yakit.SaveHTTPFlow(result.Url, result.Request,result.Response )
            if str.StringContainsAnyOfSubString(string(result.ResponseRaw), fingerUi) && result.Response.StatusCode == 200 && len(result.Response.Header["Content-Type"])>0 && str.Contains(result.Response.Header["Content-Type"][0], "html") {
                risk.NewRisk(result.Url,
                    risk.description("swagger UI 泄露"),
                    risk.solution("1、生产环境禁止访问swagger"),
                    risk.title("swagger UI 泄露"),
                    risk.request(result.RequestRaw),
                    risk.response(result.ResponseRaw),
                    risk.typeVerbose("swagger UI 未授权"),
                    risk.level("low")
                )
            }
        }
    }
}
